const val TEST_JWT_SECRET = "test-secret-with-at-least-32-bytes!"

/** Settings of the application under test. */
fun testSettings() = Settings(
    jwtSecret = TEST_JWT_SECRET,
)

/** Headers of a client allowed to call every endpoint. */
fun headers(): Map<String, String> = mapOf("Authorization" to "Bearer ${token(listOf())}")

/** Headers of a client with a valid token but no role. */
fun headersWithoutRoles(): Map<String, String> = mapOf("Authorization" to "Bearer ${token(emptyList())}")

/** A token signed with the test secret, valid for one hour. */
fun token(roles: List<String>): String = JWT.create()
    .withSubject("tests")
    .withClaim("roles", roles)
    .withExpiresAt(Date(System.currentTimeMillis() + 3_600_000))
    .sign(Algorithm.HMAC256(TEST_JWT_SECRET))

/** A valid body to create an author, with the items it refers to created first. */
