    val body = if (variant == 0) Json.parseToJsonElement("{\"name\":\"name 1\",\"email\":\"user1@example.com\",\"born\":\"2024-01-15\"}") else Json.parseToJsonElement("{\"name\":\"name 2\",\"email\":\"user2@example.com\",\"born\":\"2024-01-16\"}")
